import UIKit
import simd

// First-person weapon engine.
// Every weapon is its own rig (Resources/guns.json, generated by the gun model engine) made of
// named groups (slide / bolt / pump / mag) that animate independently: slide + bolt cycle on every
// shot, pump and bolt-action rack, magazines drop and reseat on reload, plus recoil, idle sway,
// walk bob and a randomised muzzle flash.
final class TwViewModel {
    let root = MXNode()

    private struct Rig {
        let node: MXNode
        let groups: [String: MXNode]
        let dirs: [String: MXVector3]
        let flash: MXNode?
        var att: TAttNodes? = nil
        var travel: Float = 1
    }

    private var rigs: [String: Rig] = [:]
    private var shown = ""
    private let k: Float = 0.17

    private var slideK: Float = 0
    private var recoil: Float = 0
    private var cycleT: Float = 2
    private var cycleDelay: Float = 0
    private var lastFlash = false
    private var adsK: Float = 0
    private var lastGlove = UIColor.clear
    private var lastAtt = ""
    private var gloveMats: [MXMaterial] = []
    private var sleeveMats: [MXMaterial] = []
    private var lastSleeve = UIColor.clear
    private var fingMats: [MXMaterial] = []
    private var fingBase: [Any?] = []
    private var lastFing: UIColor? = UIColor.clear

    static let viewOffDefault: (Float, Float, Float) = (-1.1, 0.6, -2.6)
    static let viewOff: [String: (Float, Float, Float)] = [
        "pistol": (-0.8, 0.45, -1.8), "eagle": (-0.8, 0.45, -1.8), "pm": (-0.8, 0.45, -1.8),
        "m4": (-1.4, 0.8, -4.0), "rifle": (-1.3, 0.7, -3.4), "awp": (-1.3, 0.7, -3.4),
        "pump": (-1.2, 0.65, -3.0), "shotgun": (-1.2, 0.65, -3.0)
    ]
    static var gloveColor = UIColor(red: 0.165, green: 0.153, blue: 0.137, alpha: 1)
    /// uniform colour of the first-person sleeves (nil keeps the model's own)
    static var sleeveColor: UIColor? = nil
    /// set when the gloves cover the fingers (nil = bare/fingerless: keep the skin texture)
    static var fingerColor: UIColor? = nil

    init() {
        root.scale = MXVector3(k, k, k)
        root.isHidden = true
        TwGunLib.load()
        TwGunLib.vmMode = true
        defer { TwGunLib.vmMode = false }
        buildKnife()
        guard let rs = TwGunLib.rigs else { return }
        defer {
            for m in gloveMats { m.diffuse.contents = TwViewModel.gloveColor }
            if let sc = TwViewModel.sleeveColor { for m in sleeveMats { m.diffuse.contents = sc } }
        }
        for (id, v) in rs {
            guard let rig = v as? [String: Any], let parts = rig["parts"] as? [[String: Any]] else { continue }
            if let g = TwGunLib.glbGun(id, arms: true, order: 1000) {
                let gun = MXNode()
                gun.isHidden = true
                gun.addChildNode(g.node)
                gloveMats += g.gloveMats
                sleeveMats += g.sleeveMats
                for m in g.fingMats where !fingMats.contains(where: { $0 === m }) { fingMats.append(m); fingBase.append(m.diffuse.contents) }
                var fl: MXNode? = nil
                if let mz = rig["muzzle"] as? [Double], mz.count == 3 {
                    let f = MuzzleFX.make()
                    f.position = MXVector3(Float(mz[0]), Float(mz[1]), Float(mz[2]))
                    f.isHidden = true
                    gun.addChildNode(f)
                    fl = f
                }
                root.addChildNode(gun)
                let attNodes = TAttBuild.build(id, into: gun, magHolder: g.groups["mag"], order: 1000)
                rigs[id] = Rig(node: gun, groups: g.groups, dirs: g.dirs, flash: fl, att: attNodes, travel: g.travel)
                continue
            }
            var buckets: [String: MXNode] = [:]
            for p in parts {
                guard let n = TwGunLib.makePart(p) else { continue }
                let gname = (p["g"] as? String) ?? ""
                let b = buckets[gname] ?? MXNode()
                b.addChildNode(n)
                buckets[gname] = b
            }
            let gun = MXNode()
            gun.isHidden = true
            var groups: [String: MXNode] = [:]
            for (gname, b) in buckets {
                let flat = b.flattenedClone()
                flat.renderingOrder = 1000
                flat.castsShadow = false
                if gname.isEmpty {
                    gun.addChildNode(flat)
                } else {
                    let holder = MXNode()
                    holder.addChildNode(flat)
                    gun.addChildNode(holder)
                    groups[gname] = holder
                }
            }
            var dirs: [String: MXVector3] = [:]
            if let an = rig["anim"] as? [String: [Double]] {
                for (key, a) in an where a.count == 3 { dirs[key] = MXVector3(Float(a[0]), Float(a[1]), Float(a[2])) }
            }
            var fl: MXNode? = nil
            if let mz = rig["muzzle"] as? [Double], mz.count == 3 {
                let f = MXNode(geometry: MXSphere(radius: 2.0))
                let fm = MXMaterial()
                fm.lightingModel = .constant
                fm.diffuse.contents = UIColor(red: 1, green: 0.88, blue: 0.45, alpha: 1)
                fm.emission.contents = UIColor(red: 1, green: 0.8, blue: 0.3, alpha: 1)
                fm.readsFromDepthBuffer = false
                fm.writesToDepthBuffer = false
                f.geometry?.firstMaterial = fm
                f.position = MXVector3(Float(mz[0]), Float(mz[1]), Float(mz[2]) - 1)
                f.renderingOrder = 2000
                f.isHidden = true
                f.castsShadow = false
                gun.addChildNode(f)
                fl = f
            }
            root.addChildNode(gun)
            let attNodes = TAttBuild.build(id, into: gun, magHolder: groups["mag"], order: 1000)
            rigs[id] = Rig(node: gun, groups: groups, dirs: dirs, flash: fl, att: attNodes)
        }
    }

    // MARK: knife

    private var swing: Float = 0

    private func kMat(_ key: String, _ r: Float, _ g: Float, _ b: Float) -> MXMaterial {
        if let m = TwGunLib.vmMats[key] ?? TwGunLib.mats[key] { return m }
        let m = MXMaterial()
        m.diffuse.contents = UIColor(red: CGFloat(r), green: CGFloat(g), blue: CGFloat(b), alpha: 1)
        return m
    }

    /// procedural combat knife in the same rig space as the guns (forward is -z, right is +x)
    private func buildKnife() {
        let steel = kMat("chrome", 0.72, 0.74, 0.77)
        let dark = kMat("dark", 0.07, 0.075, 0.08)
        let grip = kMat("grip", 0.09, 0.09, 0.1)
        let glove = kMat("glove", 0.165, 0.153, 0.137)
        func part(_ w: Float, _ h: Float, _ l: Float, _ x: Float, _ y: Float, _ z: Float, _ m: MXMaterial, _ c: Float = 0.08) -> MXNode {
            let g = MXBox(width: CGFloat(w), height: CGFloat(h), length: CGFloat(l), chamferRadius: CGFloat(c))
            g.firstMaterial = m
            let n = MXNode(geometry: g)
            n.position = MXVector3(x, y, z)
            n.renderingOrder = 1000
            n.castsShadow = false
            return n
        }
        let gun = MXNode()
        gun.isHidden = true
        // everything is built around the fist at (9, -7.3, -27) so the whole knife can pitch about the hand
        let kn = MXNode()
        kn.position = MXVector3(9, -7.3, -27)
        kn.eulerAngles = MXVector3(0.3, 0.06, 0)
        // blade (stepped taper to a point) with a dark spine and a fuller line
        kn.addChildNode(part(0.55, 3.9, 15, 0, 0.5, -11.5, steel, 0.05))
        kn.addChildNode(part(0.5, 3.0, 4.2, 0, 0.2, -20.8, steel, 0.05))
        kn.addChildNode(part(0.45, 2.0, 3.0, 0, -0.1, -23.4, steel, 0.04))
        kn.addChildNode(part(0.4, 1.0, 2.2, 0, -0.3, -25.2, steel, 0.03))
        kn.addChildNode(part(0.72, 0.5, 15, 0, 2.5, -11.5, dark, 0.04))
        kn.addChildNode(part(0.62, 0.35, 11, 0, 0.9, -10.5, dark, 0.02))
        // guard, handle, pommel
        kn.addChildNode(part(5.2, 1.0, 1.5, 0, 0.2, -3.6, steel, 0.1))
        kn.addChildNode(part(2.0, 2.5, 9.5, 0, 0, 1.2, grip, 0.25))
        kn.addChildNode(part(2.5, 2.9, 1.1, 0, 0, 6.3, steel, 0.2))
        for i in 0..<5 { kn.addChildNode(part(2.15, 0.28, 0.4, 0, 1.3, Float(-2 + i * 2), dark, 0.0)) }
        // gloved fist wrapped around the handle, thumb and forearm
        kn.addChildNode(part(3.9, 4.1, 5.2, 0, -0.1, 1.6, glove, 0.9))
        kn.addChildNode(part(1.3, 1.4, 4.4, -1.9, 1.5, 0.2, glove, 0.5))
        kn.addChildNode(part(3.0, 1.3, 4.0, 0.3, -2.2, -0.2, glove, 0.5))
        gun.addChildNode(kn)
        let fore = part(4.3, 4.5, 20, 11.8, -11.2, -13.5, glove, 1.0)
        fore.eulerAngles = MXVector3(0.18, -0.1, 0)
        gun.addChildNode(fore)
        root.addChildNode(gun)
        rigs["knife"] = Rig(node: gun, groups: [:], dirs: [:], flash: nil)
    }

    // MARK: runtime

    func show(_ id: String) {
        let gid = rigs[id] != nil ? id : "pistol"
        if TwViewModel.gloveColor != lastGlove {
            lastGlove = TwViewModel.gloveColor
            TwGunLib.vmMats["glove"]?.diffuse.contents = TwViewModel.gloveColor
            for m in gloveMats { m.diffuse.contents = TwViewModel.gloveColor }
        }
        if lastFing == nil || lastFing! != (TwViewModel.fingerColor ?? UIColor.clear) {
            lastFing = TwViewModel.fingerColor ?? UIColor.clear
            for (i, m) in fingMats.enumerated() { m.diffuse.contents = TwViewModel.fingerColor ?? fingBase[i] }
        }
        if let sc = TwViewModel.sleeveColor, sc != lastSleeve {
            lastSleeve = sc
            for m in sleeveMats { m.diffuse.contents = sc }
        }
        let attKey = gid + "|" + TAtt.viewSig(gid)
        if attKey != lastAtt {
            lastAtt = attKey
            TAtt.applyCamo(gid, set: 1)
            for (key, r) in rigs { r.att?.apply(key) }
        }
        if gid == shown { return }
        shown = gid
        let ks: Float = gid == "pistol" || gid == "eagle" || gid == "pm" ? 1 : (gid == "awp" ? 0.72 : (gid == "pump" || gid == "shotgun" || gid == "rifle" || gid == "ak" ? 0.76 : 0.85))
        root.scale = MXVector3(k * ks, k * ks, k * ks)
        for (key, r) in rigs { r.node.isHidden = key != gid }
        slideK = 0; recoil = 0; cycleT = 2; cycleDelay = 0
        for r in rigs.values { for g in r.groups.values { g.position = MXVector3Zero; g.isHidden = false } }
    }

    func flash(_ on: Bool) {
        guard let f = rigs[shown]?.flash else { return }
        if on && f.isHidden {
            MuzzleFX.pulse(f)
        }
        f.isHidden = !on
    }

    private func sm(_ a: Float, _ b: Float, _ x: Float) -> Float {
        let t = max(0, min(1, (x - a) / (b - a)))
        return t * t * (3 - 2 * t)
    }

    private func slideGroup(_ r: Rig, _ g: String, _ amount0: Float) {
        guard let n = r.groups[g], let d = r.dirs[g] else { return }
        let amount = g == "mag" ? amount0 : amount0 * r.travel
        let len = max(0.0001, sqrt(d.x * d.x + d.y * d.y + d.z * d.z))
        n.position = MXVector3(d.x / len * amount, d.y / len * amount, d.z / len * amount)
    }

    /// Call every frame. `reload` is 0...1 progress while reloading, nil otherwise.
    func update(dt: Float, t: Float, move mv: Float, kick: Float, reload: Float?, flashing: Bool, recoilScale: Float, ads adsTarget: Float = 0) {
        adsK += (adsTarget - adsK) * min(1, dt * 10)
        guard let r = rigs[shown] else { return }
        let shot = flashing && !lastFlash
        lastFlash = flashing
        if shot && shown == "knife" { swing = 1 }
        if shot && shown != "knife" {
            slideK = 1
            recoil = min(1.5, recoil + 1)
            if shown == "pump" || shown == "awp" {
                cycleDelay = shown == "awp" ? 0.28 : 0.18
                cycleT = 2
            }
        }
        slideK = max(0, slideK - dt * 11)
        recoil = max(0, recoil - dt * 8)
        if cycleDelay > 0 {
            cycleDelay -= dt
            if cycleDelay <= 0 { cycleT = 0 }
        }
        if cycleT < 1 { cycleT += dt / (shown == "awp" ? 0.75 : 0.55) }
        let cyc: Float = cycleT < 1 ? sin(Float.pi * cycleT) : 0

        var dip: Float = 0
        var magOff: Float = 0
        var magHidden = false
        var rack: Float = 0
        if let p = reload {
            dip = sm(0, 0.14, p) * (1 - sm(0.86, 1, p))
            if p >= 0.22 && p < 0.42 { magOff = sm(0.22, 0.42, p) }
            else if p >= 0.42 && p < 0.5 { magHidden = true; magOff = 1 }
            else if p >= 0.5 && p < 0.72 { magOff = 1 - sm(0.5, 0.72, p) }
            let rp = max(0, min(1, (p - 0.78) / 0.16))
            rack = sin(Float.pi * rp)
        }

        slideGroup(r, "mag", magOff * 9)
        r.groups["mag"]?.isHidden = magHidden
        switch shown {
        case "pump":
            slideGroup(r, "pump", max(cyc, rack))
            slideGroup(r, "bolt", max(cyc, rack) * 0.6)
        case "awp":
            slideGroup(r, "bolt", max(cyc, rack))
        default:
            slideGroup(r, "slide", max(slideK, rack))
            slideGroup(r, "bolt", max(slideK * 0.7, rack))
        }

        let bx = sin(t * 8) * 0.22 * mv
        let by = -abs(cos(t * 8)) * 0.18 * mv
        let ix = cos(t * 0.9) * 0.05
        let iy = sin(t * 1.7) * 0.05
        if shown == "knife" {
            swing = max(0, swing - dt * 2.7)
            let s = 1 - swing                       // 0 -> 1 across the slash
            let arc = sin(Float.pi * s) * (swing > 0 ? 1 : 0)
            let sweep = (sm(0, 1, s) - 0.5) * 2     // -1 ... 1, right to left
            root.position = MXVector3(bx + ix - (swing > 0 ? sweep * 9 : 0), by + iy + arc * 2.5, -arc * 9 + kick * 0.02)
            root.eulerAngles = MXVector3(arc * -0.35, (swing > 0 ? sweep * 0.75 : 0), (swing > 0 ? sweep * -0.9 : 0))
            return
        }
        // the gun is rotated so its bore points straight ahead (rig space is yawed), then its sight anchor is placed
        // low and to the right of the camera for the hip hold
        var rot = simd_quatf(angle: 0, axis: SIMD3<Float>(0, 1, 0))
        var anchor = SIMD3<Float>(0, 0, 0)
        var alpha: Float = 0, phi: Float = 0
        var haveMeta = false
        if let gm = TwGunLib.gmeta[shown], let tp = gm["top"] as? [Double], let mz = gm["mz"] as? [Double], tp.count == 3, mz.count == 3 {
            let dx = Float(mz[0] - tp[0]), dy = Float(mz[1] - tp[1]), dz = Float(mz[2] - tp[2])
            phi = atan2f(dx, -dz)
            alpha = -atan2f(dy, hypotf(dx, dz))
            rot = simd_quatf(angle: alpha, axis: SIMD3<Float>(1, 0, 0)) * simd_quatf(angle: phi, axis: SIMD3<Float>(0, 1, 0))
            anchor = rot.act(SIMD3<Float>(Float(tp[0]), Float(tp[1]), Float(tp[2])) * root.scale.x)
            haveMeta = true
        }
        let small = shown == "pistol" || shown == "eagle" || shown == "pm"
        let hipAnchor: SIMD3<Float> = small ? SIMD3<Float>(0.8, -0.35, -4.1) : SIMD3<Float>(1.15, -1.0, -5.4)
        let vo = TwViewModel.viewOff[shown] ?? TwViewModel.viewOffDefault
        let hipBase: SIMD3<Float> = haveMeta ? hipAnchor - anchor : SIMD3<Float>(vo.0, vo.1, vo.2)
        var pos = SIMD3<Float>(bx + ix + dip * 1.2, by + iy - dip * 4.5, kick * 0.02 + recoil * 0.9 * recoilScale) + hipBase
        var eul = SIMD3<Float>(kick * 0.004 + recoil * 0.035 * recoilScale - dip * 0.5 + alpha, phi, -dip * 0.35)
        // aim down sights: put the weapon's sight anchor on the camera axis
        if adsK > 0.002 && haveMeta {
            let k = adsK * adsK * (3 - 2 * adsK)
            let target = SIMD3<Float>(0, -0.02, -4.2) - anchor
            let calm = 1 - 0.7 * k                       // sway and bob settle when the sights are up
            let sway = pos - hipBase
            let kickZ: Float = (kick * 0.02 + recoil * 0.9 * recoilScale) * k * 0.5
            pos = hipBase * (1 - k) + target * k + sway * calm * (1 - k) + SIMD3<Float>(0, 0, kickZ)
            eul = SIMD3<Float>(alpha + (eul.x - alpha) * (1 - 0.5 * k), phi, eul.z * (1 - k))
        }
        root.position = MXVector3(pos.x, pos.y, pos.z)
        root.eulerAngles = MXVector3(eul.x, eul.y, eul.z)
    }
}

/// Shared weapon data: materials, parts and the third-person (soldier) gun templates.
enum TwGunLib {
    static var defs: [String: [String: Any]] = [:]
    /// 0 = shared (bots/world), 1 = first-person gun, 2 = gunsmith preview; separate instances so camo never leaks between them
    static var sets: [[String: MXMaterial]] = [[:], [:], [:]]
    static var setIdx = 0
    static var mats: [String: MXMaterial] { get { sets[0] } set { sets[0] = newValue } }
    static var vmMats: [String: MXMaterial] { get { sets[1] } set { sets[1] = newValue } }
    static var vmMode: Bool { get { setIdx == 1 } set { setIdx = newValue ? 1 : 0 } }
    static var rigs: [String: Any]? = nil

    // MARK: Blender-built gun models (Resources/gun_<id>.glb + gunmeta.json)
    struct GlbGun { let node: MXNode; let groups: [String: MXNode]; let dirs: [String: MXVector3]; let travel: Float; let gloveMats: [MXMaterial]; let sleeveMats: [MXMaterial]; let fingMats: [MXMaterial] }
    static let gmeta: [String: [String: Any]] = {
        guard let url = Bundle.main.url(forResource: "gunmeta", withExtension: "json") ?? Bundle.main.url(forResource: "gunmeta", withExtension: "json", subdirectory: "models"),
              let d = try? Data(contentsOf: url),
              let j = (try? JSONSerialization.jsonObject(with: d)) as? [String: [String: Any]] else { return [:] }
        return j
    }()
    /// camo-able (painted) materials of each Blender gun, keyed "<id>#<material set>", with their stock baked textures
    static var glbPaint: [String: [MXMaterial]] = [:]
    static var glbPaintBase: [String: [Any?]] = [:]
    static var glbMetal: [String: [MXMaterial]] = [:]
    static var glbMetalBase: [String: [Any?]] = [:]
    private static let armSuffix: Set<String> = ["glove", "gloveP", "sleeve", "strap", "ARMS"]

    /// loads the detailed model for a weapon; `arms` false strips the hands and sleeves (gunsmith preview)
    static func glbGun(_ id: String, arms: Bool, order: Int = 0) -> GlbGun? {
        guard let meta = gmeta[id],
              let url = Bundle.main.url(forResource: "gun_\(id)", withExtension: "glb") ?? Bundle.main.url(forResource: "gun_\(id)", withExtension: "glb", subdirectory: "models"),
              let root = MXGLTF.load(url) else { return nil }
        var groups: [String: MXNode] = [:]
        var gloves: [MXMaterial] = []
        var sleeves: [MXMaterial] = []
        var fings: [MXMaterial] = []
        var paints: [MXMaterial] = []
        var metals: [MXMaterial] = []
        func isArm(_ n: MXNode) -> Bool {
            guard let nm = n.name, let u = nm.lastIndex(of: "_") else { return false }
            return armSuffix.contains(String(nm[nm.index(after: u)...]))
        }
        func walk(_ n: MXNode) {
            for c in n.childNodes {
                if !arms && isArm(c) { c.removeFromParentNode(); continue }
                walk(c)
            }
            n.castsShadow = false
            if n.geometry != nil {
                n.renderingOrder = order
                if arms, let nm = n.name, nm.hasSuffix("_glove"), let ms = n.geometry?.materials { gloves += ms }
                if arms, let nm = n.name, nm.hasSuffix("_ARMS"), let ms = n.geometry?.materials { fings += ms }
                if arms, let nm = n.name, nm.hasSuffix("_sleeve"), let ms = n.geometry?.materials { sleeves += ms }
                if let nm = n.name, nm.hasSuffix("_QUATP"), let ms = n.geometry?.materials {
                    for m in ms where !paints.contains(where: { $0 === m }) { paints.append(m) }
                } else if let nm = n.name, nm.hasSuffix("_QUAT"), let ms = n.geometry?.materials {
                    for m in ms where !metals.contains(where: { $0 === m }) { metals.append(m) }
                }
            }
        }
        walk(root)
        glbPaint["\(id)#\(setIdx)"] = paints
        glbPaintBase["\(id)#\(setIdx)"] = paints.map { $0.diffuse.contents }
        glbMetal["\(id)#\(setIdx)"] = metals
        glbMetalBase["\(id)#\(setIdx)"] = metals.map { $0.diffuse.contents }
        for c in root.childNodes { if let nm = c.name, ["slide", "bolt", "mag", "pump"].contains(nm) { groups[nm] = c } }
        var dirs: [String: MXVector3] = [:]
        if let an = meta["anim"] as? [String: [Double]] {
            for (k, a) in an where a.count == 3 { dirs[k] = MXVector3(Float(a[0]), Float(a[1]), Float(a[2])) }
        }
        let st = Float((meta["st"] as? Double) ?? 4)
        return GlbGun(node: root, groups: groups, dirs: dirs, travel: st, gloveMats: gloves, sleeveMats: sleeves, fingMats: fings)
    }
    private static var worldCache: [String: MXNode] = [:]
    private static var worldMuzzle: [String: Float] = [:]

    static func load() {
        if rigs != nil { return }
        guard let url = Bundle.main.url(forResource: "guns", withExtension: "json"),
              let d = try? Data(contentsOf: url),
              let top = (try? JSONSerialization.jsonObject(with: d)) as? [String: Any],
              let md = top["mats"] as? [String: [String: Any]],
              let rs = top["rigs"] as? [String: Any] else { return }
        defs = md
        rigs = rs
        TWorkshop.inject()
    }

    /// re-reads guns.json and re-applies Workshop sprite guns (drops cached custom meshes/materials)
    static func reloadRigs() {
        rigs = nil
        worldCache = [:]
        worldMuzzle = [:]
        for i in 0..<sets.count { sets[i] = sets[i].filter { !$0.key.hasPrefix("cg") } }
        load()
    }

    /// flattened gun-only model for soldiers (+x forward, grip at the origin); clone it per soldier
    static func worldGun(_ id: String) -> MXNode {
        load()
        if let n = worldCache[id] { return n.clone() }
        let holder = MXNode()
        if let rig = (rigs?[id] as? [String: Any]) ?? (rigs?["pistol"] as? [String: Any]),
           let w = rig["w"] as? [String: Any], let parts = w["parts"] as? [[String: Any]] {
            let tmp = MXNode()
            for p in parts { if let n = makePart(p) { tmp.addChildNode(n) } }
            let flat = tmp.flattenedClone()
            flat.castsShadow = false
            holder.addChildNode(flat)
            worldMuzzle[id] = Float((w["mx"] as? Double) ?? 24)
        }
        worldCache[id] = holder
        return holder.clone()
    }

    static func muzzleX(_ id: String) -> Float {
        _ = worldGun(id)
        return worldMuzzle[id] ?? 24
    }

    // MARK: geometry + materials

    static func makePart(_ p: [String: Any]) -> MXNode? {
        guard let t = p["t"] as? String, let m = p["m"] as? String,
              let pos = p["p"] as? [Double], let q = p["q"] as? [Double], let s = p["s"] as? [Double],
              pos.count == 3, q.count == 4 else { return nil }
        let geo: MXGeometry
        var sc = MXVector3(1, 1, 1)
        switch t {
        case "box":
            guard s.count == 3 else { return nil }
            let b = MXBox(width: CGFloat(s[0]), height: CGFloat(s[1]), length: CGFloat(s[2]), chamferRadius: 0)
            let mn = CGFloat(min(s[0], min(s[1], s[2])))
            let want = CGFloat((p["c"] as? Double) ?? (mn < 0.5 ? 0 : 0.06))
            let c = min(want, mn * 0.45)
            if c > 0.01 { b.chamferRadius = c; b.chamferSegmentCount = 2 }
            geo = b
        case "cyl":
            guard s.count == 2 else { return nil }
            let c = MXCylinder(radius: CGFloat(s[0]), height: CGFloat(s[1]))
            c.radialSegmentCount = 18
            geo = c
        case "cone":
            guard s.count == 3 else { return nil }
            let c = MXCone(topRadius: CGFloat(s[0]), bottomRadius: CGFloat(s[1]), height: CGFloat(s[2]))
            c.radialSegmentCount = 18
            geo = c
        case "sph":
            guard s.count == 3 else { return nil }
            let sp = MXSphere(radius: 1)
            sp.segmentCount = 12
            geo = sp
            sc = MXVector3(Float(s[0]), Float(s[1]), Float(s[2]))
        default:
            guard s.count == 2 else { return nil }
            let c = MXCapsule(capRadius: CGFloat(s[0]), height: CGFloat(s[1]))
            c.radialSegmentCount = 12
            c.capSegmentCount = 4
            geo = c
        }
        geo.firstMaterial = material(m)
        let n = MXNode(geometry: geo)
        n.position = MXVector3(Float(pos[0]), Float(pos[1]), Float(pos[2]))
        n.orientation = MXVector4(Float(q[0]), Float(q[1]), Float(q[2]), Float(q[3]))
        n.scale = sc
        n.castsShadow = false
        return n
    }

    static func material(_ name: String) -> MXMaterial {
        if let m = sets[setIdx][name] { return m }
        let d = defs[name] ?? [:]
        let c = (d["c"] as? [Double]) ?? [0.5, 0.5, 0.5]
        let m = MXMaterial()
        m.lightingModel = (name == "dot") ? .constant : .blinn
        m.diffuse.contents = name == "glove"
            ? TwViewModel.gloveColor
            : UIColor(red: CGFloat(c[0]), green: CGFloat(c[1]), blue: CGFloat(c[2]), alpha: 1)
        m.specular.contents = UIColor(white: CGFloat((d["sp"] as? Double) ?? 0.2), alpha: 1)
        m.shininess = CGFloat((d["sh"] as? Double) ?? 0.2)
        let rf = (d["rf"] as? Double) ?? 0
        if rf > 0 {
            m.reflective.contents = envMap
            m.reflective.intensity = CGFloat(rf)
        }
        if let tx = d["tx"] as? String, !tx.isEmpty {
            m.multiply.contents = noise(tx)
            m.multiply.wrapS = .repeat
            m.multiply.wrapT = .repeat
        }
        if let em = d["em"] as? [Double], em.count == 3 {
            m.emission.contents = UIColor(red: CGFloat(em[0]), green: CGFloat(em[1]), blue: CGFloat(em[2]), alpha: 1)
        }
        let a = (d["a"] as? Double) ?? 1
        if a < 1 {
            m.transparency = CGFloat(a)
            m.writesToDepthBuffer = false
            m.isDoubleSided = true
        }
        sets[setIdx][name] = m
        return m
    }

    /// studio-style environment used for metal reflections
    static let envMap: UIImage = {
        let size = CGSize(width: 256, height: 128)
        return UIGraphicsImageRenderer(size: size).image { ctx in
            let g = ctx.cgContext
            let cols = [UIColor(red: 0.50, green: 0.68, blue: 0.95, alpha: 1).cgColor,
                        UIColor(red: 0.92, green: 0.93, blue: 0.95, alpha: 1).cgColor,
                        UIColor(red: 0.58, green: 0.47, blue: 0.33, alpha: 1).cgColor,
                        UIColor(red: 0.22, green: 0.18, blue: 0.13, alpha: 1).cgColor] as CFArray
            if let grad = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: cols, locations: [0, 0.48, 0.52, 1]) {
                g.drawLinearGradient(grad, start: .zero, end: CGPoint(x: 0, y: 128), options: [])
            }
            UIColor.white.withAlphaComponent(0.95).setFill()
            g.fill(CGRect(x: 36, y: 18, width: 54, height: 14))
            g.fill(CGRect(x: 170, y: 28, width: 38, height: 9))
            UIColor.white.withAlphaComponent(0.5).setFill()
            g.fill(CGRect(x: 110, y: 60, width: 30, height: 4))
        }
    }()

    static var noiseCache: [String: UIImage] = [:]

    /// near-white grayscale detail maps, applied through the material's multiply slot
    static func noise(_ kind: String) -> UIImage {
        if let i = noiseCache[kind] { return i }
        let S: CGFloat = 64
        var seed: UInt64 = 0x9E3779B97F4A7C15
        func rnd() -> CGFloat {
            seed = seed &* 6364136223846793005 &+ 1442695040888963407
            return CGFloat((seed >> 33) & 0xFFFF) / 65535
        }
        let img = UIGraphicsImageRenderer(size: CGSize(width: S, height: S)).image { ctx in
            let g = ctx.cgContext
            UIColor(white: 0.95, alpha: 1).setFill()
            g.fill(CGRect(x: 0, y: 0, width: S, height: S))
            switch kind {
            case "stipple":
                for _ in 0..<300 {
                    UIColor(white: 0.62 + rnd() * 0.3, alpha: 1).setFill()
                    let w = 0.7 + rnd() * 1.0
                    g.fillEllipse(in: CGRect(x: rnd() * S, y: rnd() * S, width: w, height: w))
                }
            case "knurl":
                UIColor(white: 0.62, alpha: 1).setStroke()
                g.setLineWidth(1)
                var i: CGFloat = -64
                while i < 128 {
                    g.move(to: CGPoint(x: i, y: 0)); g.addLine(to: CGPoint(x: i + 64, y: 64))
                    g.move(to: CGPoint(x: i + 64, y: 0)); g.addLine(to: CGPoint(x: i, y: 64))
                    i += 6
                }
                g.strokePath()
            case "brushed":
                for _ in 0..<100 {
                    UIColor(white: 0.74 + rnd() * 0.26, alpha: 1).setFill()
                    g.fill(CGRect(x: 0, y: rnd() * S, width: S, height: 1))
                }
            case "wood":
                for _ in 0..<30 {
                    UIColor(white: 0.55 + rnd() * 0.3, alpha: 1).setFill()
                    g.fill(CGRect(x: rnd() * S, y: 0, width: 1 + rnd() * 2.2, height: S))
                }
            default: break
            }
        }
        noiseCache[kind] = img
        return img
    }
}
